/* ---------- Health score ---------- */
.hsx{padding:14px;display:flex;flex-direction:column;gap:12px;--hs-ok:#16b558;--hs-bad:#e5383b}
:root[data-theme="dark"] .hsx{--hs-ok:#34d27a;--hs-bad:#ff5c5f}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .hsx{--hs-ok:#34d27a;--hs-bad:#ff5c5f}}
.hsx-top{display:flex;align-items:center;gap:14px}
.hsx-g{position:relative;width:120px;height:72px;flex:none}
.hsx-g svg{width:100%;height:100%;overflow:visible}
.hsx-g path{fill:none;stroke-width:9;stroke-linecap:round}
.hsx-g .tr{stroke:var(--line)}
.hsx-g .fl{stroke:var(--accent);stroke-dasharray:157;stroke-dashoffset:157;transition:stroke-dashoffset 1.2s var(--ease),stroke .4s}
.hsx-v{position:absolute;left:0;right:0;bottom:0;display:flex;flex-direction:column;align-items:center;line-height:1.1}
.hsx-v b{font-size:20px;font-weight:500}
.hsx-v span{font-size:11px}
.hsx-s{display:flex;flex-direction:column;font-size:13.5px}
.hsx-s b{font-weight:500}
.hsx-st{font-size:12.5px}
.hsx-list{display:flex;flex-direction:column;gap:2px}
.hsx-c{border-radius:10px;transition:background .2s}
.hsx-c:hover,.hsx-c.open{background:var(--row)}
.hsx-ch{display:flex;align-items:center;gap:10px;width:100%;padding:8px;font-size:13px;text-align:left}
.hsx-ch .t{flex:1}
.hsx-ch .bar{width:70px;height:5px;border-radius:3px;background:var(--line);overflow:hidden}
.hsx-ch .bar i{display:block;height:100%;border-radius:3px;transition:width .8s var(--ease),background .4s}
.hsx-ch .v{width:26px;text-align:right;font-size:12px;color:var(--fg2)}
.hsx-ch>svg{color:var(--muted);transition:transform .35s var(--ease)}
.hsx-c.open .hsx-ch>svg{transform:rotate(90deg)}
.hsx-d{padding:0 8px 10px 8px;font-size:12.5px;color:var(--fg2);display:flex;align-items:center;gap:10px;line-height:1.45}
.hsx-d span{flex:1}

DM.def('health-score', (r, c) => {
  const K = [['Token usage',96,'All colours come from the library'],['Contrast',88,'2 text pairs below AA on the pricing page',1],['Component reuse',74,'11 detached instances in Checkout',1],['Naming',91,'Layer names follow the convention']];
  const list = $('.hsx-list', r), fl = $('.hsx-g .fl', r), vb = $('.hsx-v b', r), st = $('.hsx-st', r);
  let score = 0;
  const col = v => v >= 90 ? 'var(--hs-ok)' : v >= 80 ? 'var(--accent)' : 'var(--hs-bad)';
  function total(){ const t = Math.round(K.reduce((a, k) => a + k[1], 0) / K.length); fl.style.strokeDashoffset = 157 * (1 - t / 100); fl.style.stroke = col(t); tween(score, t, 1000, n => { score = n; vb.textContent = Math.round(n); }); const n = K.filter(k => k[1] < 90).length; swap(st, n ? (t >= 85 ? 'Good' : 'Fair') + ', ' + n + (n > 1 ? ' checks need' : ' check needs') + ' work' : 'Excellent, all checks pass'); }
  list.innerHTML = K.map(k => `<div class="hsx-c"><button class="hsx-ch"><span class="t">${k[0]}</span><span class="bar"><i style="width:0"></i></span><span class="v num">${k[1]}</span>${I('chev-r','xs')}</button><div class="fold shut"><div><div class="hsx-d"><span>${k[2]}</span>${k[3] ? `<button class="pill soft sm">${I('wand','xs')}Fix</button>` : ''}</div></div></div></div>`).join('');
  $$('.hsx-c', list).forEach((el, i) => {
    $('.hsx-ch', el).onclick = () => { const o = !el.classList.contains('open'); el.classList.toggle('open', o); $('.fold', el).classList.toggle('shut', !o); };
    const bar = () => { const b = $('.bar i', el); b.style.width = K[i][1] + '%'; b.style.background = col(K[i][1]); };
    c.later(300 + i * 80, bar);
    const fx = $('.hsx-d .pill', el);
    if (fx) fx.onclick = () => c.run(async () => { fx.innerHTML = '<span class="spin"></span>'; await c.wait(900); K[i][1] = i === 1 ? 97 : 93; K[i][3] = 0; bar(); tween(+$('.v', el).textContent, K[i][1], 700, n => $('.v', el).textContent = Math.round(n)); swap($('.hsx-d span', el), i === 1 ? 'Fixed. Both pairs now pass AA' : 'Fixed. Reattached 11 instances'); fx.remove(); total(); });
  });
  c.later(280, total);
});
